from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np

# Define SMILES strings for the three molecules
smiles_list = {
    'Aspirin': 'CC(=O)Oc1ccccc1C(=O)O',
    'Caffeine': 'CN1C=NC2=C1C(=O)N(C(=O)N2C)C',
    'Ibuprofen': 'CC(C)Cc1ccc(cc1)C(C)C(=O)O'
}

# Function to compute adjacency matrix from RDKit molecule
def get_adjacency_matrix(mol):
    return Chem.rdmolops.GetAdjacencyMatrix(mol)

# Function to compute ECFP4 fingerprint
def get_ecfp4_fp(mol):
    return AllChem.GetMorganFingerprintAsBitVect(mol, radius=2, nBits=1024)

# Process molecules
mols = {name: Chem.MolFromSmiles(smiles) for name, smiles in smiles_list.items()}
adj_matrices = {name: get_adjacency_matrix(mol) for name, mol in mols.items()}

# Compute ECFP4 fingerprints and Tanimoto similarities
fingerprints = {name: get_ecfp4_fp(mol) for name, mol in mols.items()}
names = list(smiles_list.keys())
n = len(names)
similarity_matrix = np.zeros((n, n))

for i in range(n):
    for j in range(i, n):
        if i == j:
            similarity_matrix[i, j] = 1.0
        else:
            tanimoto = DataStructs.TanimotoSimilarity(fingerprints[names[i]], fingerprints[names[j]])
            similarity_matrix[i, j] = tanimoto
